insert into public.products (id, slug, brand_id, style, name, badge, tagline, overview, mrp, in_stock, published, rating, review_count)
values
('22222222-2222-4222-8222-222222222001', 'signia-pure-charge-go-ix', '11111111-1111-4111-8111-111111111001', 'RIC', $seed$Signia Pure Charge&Go IX$seed$, $seed$36 Hours Battery$seed$, $seed$AI-powered speech clarity in noisy environments$seed$, $seed$Pure Charge&Go IX is Signia’s everyday RIC for people who move through noise — offices, traffic, family dinners. Integrated Xperience tracks more than one talker so speech does not collapse the moment you turn your head. Lithium-ion charging is built in; a full charge is aimed at a long waking day plus a buffer.$seed$, 245000, true, true, 5, 412),
('22222222-2222-4222-8222-222222222002', 'phonak-audeo-lumity-l90', '11111111-1111-4111-8111-111111111002', 'RIC', $seed$Phonak Audéo Lumity L90-R$seed$, $seed$AutoSense OS 5.0$seed$, $seed$Adaptive noise reduction for conversations in motion$seed$, $seed$Audéo Lumity L90-R is Phonak’s premium rechargeable RIC. AutoSense OS 5.0 switches scenes for you so you are not hunting through programs. It is the model we trial when speech in a car, a classroom or a restaurant is the main complaint — and when a Roger microphone may be added later.$seed$, 265000, true, true, 4.9, 386),
('22222222-2222-4222-8222-222222222003', 'widex-moment-sheer-s440', '11111111-1111-4111-8111-111111111003', 'RIC', $seed$Widex Moment Sheer S440$seed$, $seed$PureSound™$seed$, $seed$Zero-delay sound for a more natural listening experience$seed$, $seed$Moment Sheer is the Widex people describe as ‘less processed’. PureSound cuts the lag that makes some aids sound like a loudspeaker next to your ear. We put it on the trial board for musicians, first-time wearers, and anyone who has rejected other brands for sounding fake.$seed$, 198000, true, true, 4.8, 254),
('22222222-2222-4222-8222-222222222004', 'oticon-intent-1', '11111111-1111-4111-8111-111111111004', 'RIC', $seed$Oticon Intent 1$seed$, $seed$AI Speech Clarity$seed$, $seed$4D sensor technology that follows your listening intent$seed$, $seed$Intent 1 is Oticon’s flagship BrainHearing RIC. Instead of shrinking the world to a narrow beam, it keeps more of the scene and uses 4D sensors — conversation, motion, head and body — to guess what you are trying to hear. It is the trial we run when people hate ‘tunnel hearing’.$seed$, 275000, true, true, 5, 301),
('22222222-2222-4222-8222-222222222005', 'starkey-genesis-ai-2400', '11111111-1111-4111-8111-111111111005', 'RIC', $seed$Starkey Genesis AI 2400$seed$, $seed$Edge Mode+$seed$, $seed$On-device AI that boosts speech in restaurants and traffic$seed$, $seed$Genesis AI 2400 puts a neural processor on the chip so speech is lifted while you are still in the noise. Edge Mode+ is a tap when a restaurant or gust of wind overwhelms the automatic program. Optional wellness tools stay off unless you ask for them.$seed$, 230000, true, true, 4.8, 198),
('22222222-2222-4222-8222-222222222006', 'signia-styletto-ix', '11111111-1111-4111-8111-111111111001', 'BTE', $seed$Signia Styletto IX$seed$, $seed$Designer Slim RIC$seed$, $seed$Slim rechargeable design with all-day Bluetooth streaming$seed$, $seed$Styletto IX is the Signia people pick when they refuse a ‘medical’ look. The slim stick sits behind the ear, charges in a compact case, and still runs Integrated Xperience for speech in motion. It is a style choice that does not have to mean a weak prescription.$seed$, 175000, true, true, 4.9, 167),
('22222222-2222-4222-8222-222222222007', 'phonak-naida-lumity-l70', '11111111-1111-4111-8111-111111111002', 'BTE', $seed$Phonak Naída Lumity L70$seed$, $seed$Power BTE$seed$, $seed$High-power amplification for severe-to-profound loss$seed$, $seed$Naída Lumity L70 is a power BTE for severe-to-profound loss. It is built to stay clean at high gain — feedback, headroom and a robust hook or slim tube — and it still talks to AutoSense and Roger when a partner’s voice needs a microphone, not just more volume.$seed$, 185000, true, true, 4.7, 142),
('22222222-2222-4222-8222-222222222008', 'widex-unique-440-cic', '11111111-1111-4111-8111-111111111003', 'CIC', $seed$Widex Unique 440 CIC$seed$, $seed$Nearly Invisible$seed$, $seed$Custom canal fit with discreet everyday wear$seed$, $seed$Unique 440 CIC is a custom canal aid for people who will not wear anything behind the ear. It sits in the canal, uses your own ear acoustics, and stays off Bluetooth so there is no radio in a tiny shell. Best when the audiogram and ear canal can actually take a CIC.$seed$, 125000, true, true, 4.6, 98),
('22222222-2222-4222-8222-222222222009', 'oticon-own-2-iic', '11111111-1111-4111-8111-111111111004', 'IIC', $seed$Oticon Own 2 IIC$seed$, $seed$Invisible In Canal$seed$, $seed$Deep-fit custom shell that stays out of sight$seed$, $seed$Oticon Own 2 sits deep in the canal so even a CIC looks obvious by comparison. It is for vanity-first wearers whose audiogram and anatomy allow an IIC. BrainHearing ideas still apply, but physics wins: tiny batteries, no streaming, careful insertion.$seed$, 145000, true, true, 4.7, 121),
('22222222-2222-4222-8222-222222222010', 'signia-insio-charge-go-ix', '11111111-1111-4111-8111-111111111001', 'ITE', $seed$Signia Insio Charge&Go IX$seed$, $seed$Custom Rechargeable$seed$, $seed$Custom ITE with contactless charging and Bluetooth$seed$, $seed$Insio Charge&Go IX is a custom in-the-ear aid that charges without metal contacts and still runs IX processing plus Bluetooth. It is the middle path: more discreet than a RIC, more features than a tiny CIC, for people who want custom and rechargeable.$seed$, 165000, true, true, 4.8, 88),
('22222222-2222-4222-8222-222222222011', 'phonak-virto-paradise-p90', '11111111-1111-4111-8111-111111111002', 'ITC', $seed$Phonak Virto Paradise P90$seed$, $seed$Custom ITC$seed$, $seed$In-the-canal custom fit tuned for speech in noise$seed$, $seed$Virto Paradise P90 is a custom in-the-canal Phonak: more visible than an IIC, far less hardware than a RIC. Paradise-era wireless and speech tools sit in a shell that uses your canal. We trial it when someone wants custom cosmetics but still needs phone streaming.$seed$, 155000, true, true, 4.6, 76),
('22222222-2222-4222-8222-222222222012', 'resound-nexia-r', '11111111-1111-4111-8111-111111111006', 'RIC', $seed$ReSound Nexia R$seed$, $seed$Auracast Ready$seed$, $seed$Next-gen Bluetooth LE Audio with organic sound quality$seed$, $seed$Nexia R is ReSound’s rechargeable RIC with Bluetooth LE Audio and Auracast on the roadmap for venues and TVs. M&RIE — a microphone in the ear canal — uses your pinna so direction does not feel ‘inside the processor’. We trial it for iPhone-heavy lives and for people who want spatial, organic sound.$seed$, 215000, true, true, 4.7, 134);
