insert into public.product_highlights (product_id, title, body, sort_order) values
('22222222-2222-4222-8222-222222222001', $seed$Speech in motion, not only in a still room$seed$, $seed$IX analyses several moving speakers at once. That matters in a clinic corridor, a wedding hall or a shop floor — places where older ‘speech focus’ programs lock onto one spot and lose everyone else.$seed$, 0),
('22222222-2222-4222-8222-222222222001', $seed$Own Voice Processing$seed$, $seed$Your voice is handled on a separate path so it does not boom or sound hollow while other people are amplified. First-time users often notice this within the first hour of a trial.$seed$, 1),
('22222222-2222-4222-8222-222222222001', $seed$All-day rechargeable wear$seed$, $seed$The Charge&Go case tops the aids overnight. We check real wearing hours at the fitting so you are not left short on a long day out.$seed$, 2),
('22222222-2222-4222-8222-222222222001', $seed$Bluetooth streaming and the Signia app$seed$, $seed$Calls and media stream to both ears. The app lets us nudge programs remotely after you have lived with the sound for a week — without another full clinic visit unless you want one.$seed$, 3),
('22222222-2222-4222-8222-222222222002', $seed$AutoSense OS 5.0$seed$, $seed$The aid recognises quiet, noise, music, wind and speech-in-noise, then blends programs instead of making you tap a button every time the room changes.$seed$, 0),
('22222222-2222-4222-8222-222222222002', $seed$Speech from the side and behind$seed$, $seed$Lumity is tuned for conversation that is not always in front of you — a partner in the passenger seat, a grandchild tugging your sleeve, a colleague walking beside you.$seed$, 1),
('22222222-2222-4222-8222-222222222002', $seed$Universal Bluetooth and hands-free calls$seed$, $seed$Pairs widely across phones. Hands-free calling on supported models means the phone can stay in a bag or on the table.$seed$, 2),
('22222222-2222-4222-8222-222222222002', $seed$Ready for Roger when you need more$seed$, $seed$If a spouse’s voice still disappears at a noisy table, we can add a Roger microphone later without changing the whole fitting philosophy.$seed$, 3),
('22222222-2222-4222-8222-222222222003', $seed$PureSound / ZeroDelay path$seed$, $seed$Processing delay is cut so your brain is less likely to hear that classic echo against your own footsteps, crockery or piano. Music and room tone stay textured instead of flattened.$seed$, 0),
('22222222-2222-4222-8222-222222222003', $seed$SoundSense Learn$seed$, $seed$You choose between two sound samples in the app. Over a few days the aid learns whether you prefer a warmer or more speech-forward mix — useful if you cannot describe sound in clinic jargon.$seed$, 1),
('22222222-2222-4222-8222-222222222003', $seed$Sheer RIC comfort$seed$, $seed$A smaller RIC housing that sits closer to the ear. We still verify with real-ear measures so ‘natural’ does not mean under-amplified.$seed$, 2),
('22222222-2222-4222-8222-222222222003', $seed$Rechargeable everyday wear$seed$, $seed$Dock overnight. Widex sound plus lithium-ion is the combination most of our Sheer patients actually live with, not a demo-only setting.$seed$, 3),
('22222222-2222-4222-8222-222222222004', $seed$4D sensors for listening intent$seed$, $seed$The aid notices if you turn toward a talker, lean in, or start walking. Support for speech follows that intent rather than staying glued to whichever noise is loudest.$seed$, 0),
('22222222-2222-4222-8222-222222222004', $seed$On-chip deep neural network$seed$, $seed$A DNN trained on real-world sound separates speech from noise without the dead, boxed-in character of aggressive older noise reduction.$seed$, 1),
('22222222-2222-4222-8222-222222222004', $seed$BrainHearing scene access$seed$, $seed$Oticon’s bet is that your brain still wants spatial cues — a waiter at the side, traffic behind — so you stay oriented, not just ‘in speech mode’.$seed$, 2),
('22222222-2222-4222-8222-222222222004', $seed$Rechargeable with Companion app$seed$, $seed$Charge overnight, stream from the phone, and let us fine-tune after a week of real meals and commutes, not only the quiet booth.$seed$, 3),
('22222222-2222-4222-8222-222222222005', $seed$On-device Genesis AI$seed$, $seed$Machine learning runs on the aid, not in the cloud. Speech in a canteen or on a flyover is boosted without waiting for a phone connection.$seed$, 0),
('22222222-2222-4222-8222-222222222005', $seed$Edge Mode+$seed$, $seed$When the automatic scene is not enough, a tap asks the aid for a short, aggressive clean-up — a rescue, not a new default that makes every room sound thin.$seed$, 1),
('22222222-2222-4222-8222-222222222005', $seed$My Starkey / Thrive app$seed$, $seed$Streaming, volume and program control from the phone. Fall-alert and activity features exist on this family; we enable only what you actually want.$seed$, 2),
('22222222-2222-4222-8222-222222222005', $seed$Rechargeable RIC comfort$seed$, $seed$Lithium-ion receivers-in-canal with overnight charging. We set physical fit and venting so AI processing is not fighting an uncomfortable shell.$seed$, 3),
('22222222-2222-4222-8222-222222222006', $seed$Designer slim housing$seed$, $seed$A narrow silhouette that reads closer to an earbud stem than a classic BTE. Hair and glasses still need a proper fit check — slim is not the same as invisible.$seed$, 0),
('22222222-2222-4222-8222-222222222006', $seed$IX speech processing in a small body$seed$, $seed$You keep moving-talker support and Own Voice Processing, not a stripped ‘fashion’ program. We verify gain with real-ear so the look does not cost audibility.$seed$, 1),
('22222222-2222-4222-8222-222222222006', $seed$Portable rechargeable case$seed$, $seed$The case is designed to live in a bag or on a nightstand. We show you a realistic on-ear time so the slimmer battery is not a surprise on a wedding day.$seed$, 2),
('22222222-2222-4222-8222-222222222006', $seed$Bluetooth and discreet controls$seed$, $seed$Stream calls and media; use the app or a tap for volume. Good for people who will not wear a larger RIC for vanity reasons but still work in noise.$seed$, 3),
('22222222-2222-4222-8222-222222222007', $seed$Headroom for severe-to-profound loss$seed$, $seed$Enough amplification without the aid screaming into feedback the moment you hug someone or wear a helmet. Earmould choice is part of the fitting, not an afterthought.$seed$, 0),
('22222222-2222-4222-8222-222222222007', $seed$Lumity speech tools at high gain$seed$, $seed$Power does not mean a 1990s ‘loud all the time’ sound. AutoSense still shifts for noise, wind and speech so shouting environments are not unbearable.$seed$, 1),
('22222222-2222-4222-8222-222222222007', $seed$Roger-ready when volume is not enough$seed$, $seed$Distance and noise still beat raw gain. A Roger mic for a spouse or teacher is often the difference between ‘I hear noise’ and ‘I hear words’.$seed$, 2),
('22222222-2222-4222-8222-222222222007', $seed$Rechargeable power users$seed$, $seed$Lithium-ion in a larger BTE body typically outlasts slim RICs. We confirm charger habits so a profound loss is never paired with a dead battery at 4 pm.$seed$, 3),
('22222222-2222-4222-8222-222222222008', $seed$Custom shell from your ear impression$seed$, $seed$We take impressions so the aid locks in without rubbing. A CIC that is ‘almost right’ will whistle or hurt — the shell is the product as much as the chip.$seed$, 0),
('22222222-2222-4222-8222-222222222008', $seed$Discreet in conversation and on camera$seed$, $seed$Little to no hardware over the pinna. Glasses, masks and helmets do not fight a RIC wire. Makeup and hair stay simpler.$seed$, 1),
('22222222-2222-4222-8222-222222222008', $seed$Widex sound in a small package$seed$, $seed$The goal is still a natural, less processed tone. Battery size and venting limit how much wireless we can add — we are honest about that before you commit.$seed$, 2),
('22222222-2222-4222-8222-222222222008', $seed$When CIC is the wrong choice$seed$, $seed$Very severe loss, frequent ear infections, or a canal that cannot hold a shell — we will steer you to a RIC instead of forcing invisible at the cost of hearing.$seed$, 3),
('22222222-2222-4222-8222-222222222009', $seed$Deep invisible fit$seed$, $seed$Placed in the second bend of the canal when anatomy allows. Friends and colleagues typically do not see it in normal conversation or on a video call.$seed$, 0),
('22222222-2222-4222-8222-222222222009', $seed$Your pinna does the spatial work$seed$, $seed$Because nothing sits over the ear, the folds of the outer ear keep doing their job. Direction often feels more ‘in the world’ than a closed RIC.$seed$, 1),
('22222222-2222-4222-8222-222222222009', $seed$Custom medical-grade shell$seed$, $seed$Impression, scan and a handling line or removal filament we teach you to use. IICs that are too deep without training get left in a drawer.$seed$, 2),
('22222222-2222-4222-8222-222222222009', $seed$Clear limits, said up front$seed$, $seed$No Bluetooth, smaller battery, not for every loss or every canal. If you need streaming or severe-loss power, Own is the wrong hero — we will say so.$seed$, 3),
('22222222-2222-4222-8222-222222222010', $seed$Contactless custom charging$seed$, $seed$Drop the shells in the charger — no pins to corrode with sweat or humidity, a real issue in Indian summers for older contact-charge customs.$seed$, 0),
('22222222-2222-4222-8222-222222222010', $seed$IX in a custom shell$seed$, $seed$Moving-speech support and Own Voice Processing in a device that fills the concha or canal, not a tube over the ear. Glasses and masks stay easier.$seed$, 1),
('22222222-2222-4222-8222-222222222010', $seed$Bluetooth without a behind-the-ear radio$seed$, $seed$Streaming from a custom ITE is the reason many patients step up from CIC. We check ear size so the antenna and battery still fit comfortably.$seed$, 2),
('22222222-2222-4222-8222-222222222010', $seed$Made around your ear, not a one-size RIC$seed$, $seed$Impression, colour options, and a wax system we teach you to maintain. Custom only works if after-care is as serious as the first fit.$seed$, 3),
('22222222-2222-4222-8222-222222222011', $seed$ITC custom cosmetics$seed$, $seed$Fills part of the canal and bowl — noticeable if someone looks, invisible from most conversational distances. A practical compromise versus deep IIC.$seed$, 0),
('22222222-2222-4222-8222-222222222011', $seed$Paradise speech in noise$seed$, $seed$Phonak’s speech-in-noise DNA in a custom form. We still run real-ear; a pretty shell that is under-fit is just an expensive earplug.$seed$, 1),
('22222222-2222-4222-8222-222222222011', $seed$Wireless without a RIC wire$seed$, $seed$Selected Virto Paradise models stream. If calls are daily life, this is often a better custom than a non-wireless CIC.$seed$, 2),
('22222222-2222-4222-8222-222222222011', $seed$Moulded for Indian wear conditions$seed$, $seed$Sweat, glasses and helmets are part of the impression conversation. We pick varnish, venting and a removal notch you can actually use.$seed$, 3),
('22222222-2222-4222-8222-222222222012', $seed$M&RIE third microphone$seed$, $seed$A mic in the canal lets the folds of your outer ear shape sound before the chip sees it. Depth and ‘out of my head’ location are the usual comments after a side-by-side with a standard RIC.$seed$, 0),
('22222222-2222-4222-8222-222222222012', $seed$Bluetooth LE Audio and Auracast$seed$, $seed$Newer wireless than classic Bluetooth streaming. Auracast is the public-broadcast standard arriving in airports, halls and TVs — Nexia is built to join that, not only pair to one phone.$seed$, 1),
('22222222-2222-4222-8222-222222222012', $seed$Organic Hearing tuning$seed$, $seed$ReSound’s brief is to keep your own ear in the loop. We still match prescription targets; organic is not an excuse for a weak first fit.$seed$, 2),
('22222222-2222-4222-8222-222222222012', $seed$GN / Jabra call quality$seed$, $seed$Same group as Jabra headsets. If your day is calls on iPhone or Android, this is often the cleanest wireless demo we run next to Signia or Phonak.$seed$, 3);
